def _is_number(v) -> bool:
    return isinstance(v, (int, float)) and not isinstance(v, bool)


class _Weak:
    """A DECIMAL literal in a CASE branch: it takes the type of a FLOAT branch next to it, like DuckDB."""
    def __init__(self, scalar):
        self.scalar, self.type = scalar, scalar.type


def case_literal(v):
    """A CASE branch literal as an Arrow scalar of its SQL type: integers int64, an exponent (DOUBLE) float
    float64, a DECIMAL float a ``_Weak`` float64, bool, str; None (the NULL branch) stays None."""
    import datetime as _dt
    if v is None:
        return None
    if isinstance(v, (bool, np.bool_)):
        return _npscalar(bool(v), type=pa.bool_())
    if isinstance(v, (int, np.integer)):
        return _npscalar(int(v), type=pa.int64())
    if isinstance(v, (float, np.floating)):
        x = _npscalar(float(v), type=pa.float64())
        return x if isinstance(v, np.floating) else _Weak(x)
    return _npscalar(v) if isinstance(v, (str, _dt.date, np.datetime64)) else v


def _supertype(ta, tb, weak_a=False, weak_b=False):
    """DuckDB's common type of two branch types (CASE, COALESCE): equal types stay, integers widen to int64, a
    FLOAT column next to an integer or a DECIMAL literal (``weak``) stays float32 (only a DOUBLE widens it), any
    other number mix is float64, string and large_string are one family. A NULL branch (None) takes the other's
    type. Mixing text with numbers raises, as DuckDB does."""
    num = lambda t: pa.types.is_integer(t) or pa.types.is_floating(t) or pa.types.is_decimal(t)
    text = lambda t: pa.types.is_string(t) or pa.types.is_large_string(t)
    if ta is None or tb is None or ta == tb:
        return ta or tb
    if pa.types.is_integer(ta) and pa.types.is_integer(tb):
        return pa.int64()
    if text(ta) and text(tb):
        return pa.large_string()
    if num(ta) and num(tb):
        f32 = pa.float32()
        keeps = lambda t, w: pa.types.is_integer(t) or w         # what a FLOAT column keeps its type next to
        return f32 if (ta == f32 and keeps(tb, weak_b)) or (tb == f32 and keeps(ta, weak_a)) else pa.float64()
    if pa.types.is_date(ta) and pa.types.is_date(tb):
        return pa.date32()
    if pa.types.is_temporal(ta) and pa.types.is_temporal(tb) and not (pa.types.is_time(ta) or pa.types.is_time(tb)
                                                                     or pa.types.is_duration(ta) or pa.types.is_duration(tb)):
        # a date next to a timestamp is a timestamp of that timestamp's unit and zone; two timestamps take the finer
        # unit (DuckDB: TIMESTAMP_S next to TIMESTAMP_NS is TIMESTAMP_NS); a zone and no zone do not mix
        if pa.types.is_date(ta) or pa.types.is_date(tb):
            return tb if pa.types.is_date(ta) else ta
        if (ta.tz is None) != (tb.tz is None):
            raise TypeError(f"no common type: {ta} and {tb}")
        units = ("s", "ms", "us", "ns")
        return ta if units.index(ta.unit) >= units.index(tb.unit) else tb
    raise TypeError(f"no common type: {ta} and {tb}")


def _branches(vals):
    """The branches of a CASE / COALESCE as Arrow values: a ``_Weak`` literal unwrapped (and flagged), dictionaries
    decoded, NULL (None) kept."""
    from .arrow_dict import decode as _decode
    weak = [isinstance(x, _Weak) for x in vals]
    return [None if x is None else _decode(x.scalar if isinstance(x, _Weak) else x) for x in vals], weak


def _fit(x, want, like):
    """Branch ``x`` as type ``want``; a NULL branch is NULL of that type, as long as ``like`` (an array or scalar)."""
    if x is None:
        return pa.scalar(None, type=want) if isinstance(like, pa.Scalar) else pa.nulls(len(like), want)
    return x if x.type == want else pc.cast(x, want, safe=False)


def case_when_arrow(cond, then, else_):
    """Arrow CASE WHEN: ``then`` / ``else_`` are Arrow values or None (a NULL branch). The result has the
    common type of the branches like DuckDB (``_supertype``); all NULL is int32. A null condition is not true."""
    (then, else_), weak = _branches([then, else_])
    ta, tb = (None if x is None else x.type for x in (then, else_))
    try:
        want = _supertype(ta, tb, *weak) or pa.int32()
    except TypeError:
        raise TypeError(f"CASE branches have no common type: {ta} and {tb}") from None
    cond = pc.fill_null(cond, _npscalar(False, type=pa.bool_()))
    return pc.if_else(cond, _fit(then, want, cond), _fit(else_, want, cond))


def coalesce_arrow(*vals):
    """Arrow COALESCE(a, b, ...): the first non-NULL value per row, of the common type of the arguments like
    DuckDB (``_supertype``, folded left to right). ``vals`` are Arrow values or None (a NULL literal); at least
    one must be an array, the length of the result."""
    vals, weak = _branches(vals)
    want, acc_weak = None, False
    for x, w in zip(vals, weak):
        if x is None:
            continue
        if want is None:
            want, acc_weak = x.type, w
            continue
        try:
            want = _supertype(want, x.type, acc_weak, w)
        except TypeError:
            raise TypeError(f"COALESCE arguments have no common type: {want} and {x.type}") from None
        acc_weak = acc_weak and w
    return pc.coalesce(*(_fit(x, want, x) for x in vals if x is not None))


def branch_values(args, ev):
    """The branches of a CASE / COALESCE as Arrow values: a literal as ``case_literal`` (its SQL type), else ``ev(arg)``."""
    return [case_literal(a.args[0]) if a.op == "lit" else ev(a) for a in args]


_CAST_TYPES = {"float32": pa.float32, "float64": pa.float64, "int8": pa.int8, "int16": pa.int16,
               "int32": pa.int32, "int64": pa.int64}


def cast_arrow(x, name):
    """``CAST(x AS <name>)`` for the number types, as DuckDB casts: a float rounds half to even into an integer, a
    value that does not fit raises (an integer into a float rounds, as DuckDB's does)."""
    t = _CAST_TYPES[name]()
    if x.type == t:
        return x
    if pa.types.is_floating(x.type) and pa.types.is_integer(t):
        return pc.cast(pc.round(x, 0, round_mode="half_to_even"), t)
    out = pc.cast(x, t, safe=pa.types.is_integer(t))
    if pa.types.is_float32(t) and pa.types.is_float64(x.type) and bool(pc.any(pc.and_(pc.is_inf(out), pc.is_finite(x))).as_py()):
        raise OverflowError("value out of range for FLOAT")
    return out


def add_interval_arrow(x, micros):
    """``x + INTERVAL`` (a fixed length, in microseconds) for a DATE or a timestamp: DuckDB's result is a TIMESTAMP
    (microseconds, in the argument's zone), a DATE too."""
    t = x.type
    if not (pa.types.is_date(t) or pa.types.is_timestamp(t)):
        raise TypeError(f"an INTERVAL can be added to a DATE or TIMESTAMP, not to {t}")
    x = pc.cast(x, pa.timestamp("us", getattr(t, "tz", None)), safe=False)
    return pc.add(x, _npscalar(np.timedelta64(int(micros), "us")))


def abs_arrow(x):
    """``ABS(x)`` in the argument's own type; an integer minimum raises (DuckDB's overflow error)."""
    return pc.abs_checked(x) if pa.types.is_integer(x.type) else pc.abs(x)


def _numeric_literal(x):
    """The Python value of a numeric literal operand (a Python number or an Arrow scalar), else None."""
    if _is_number(x):
        return x
    if isinstance(x, pa.Scalar) and (pa.types.is_integer(x.type) or pa.types.is_floating(x.type)):
        return x.as_py()
    return None


def _align_literals(lhs, rhs):
    """A numeric literal compared with a float32 column becomes a float32 scalar.

    Arrow would widen the column to float64 and compare it with the double nearest the
    decimal literal, so `l_discount <= 0.07` dropped every row whose float32 value is the
    float32 nearest 0.07 (it is 0.07000000029802322 > 0.07).  Comparing in the column's
    own precision is what DuckDB does on DECIMAL and what NumPy 2 does."""
    def is_f32(x):
        return not isinstance(x, pa.Scalar) and hasattr(x, "type") and pa.types.is_float32(x.type)
    def is_f64(x):
        return not isinstance(x, pa.Scalar) and hasattr(x, "type") and pa.types.is_float64(x.type)
    def is_int(x):
        return not isinstance(x, pa.Scalar) and hasattr(x, "type") and pa.types.is_integer(x.type)
    r, l = _numeric_literal(rhs), _numeric_literal(lhs)
    if r is not None and is_f32(lhs):
        rhs = _npscalar(float(r), type=pa.float32())
    elif l is not None and is_f32(rhs):
        lhs = _npscalar(float(l), type=pa.float32())
    elif r is not None and is_f64(lhs):                  # an integer past 2**53: Arrow refuses the implicit cast, DuckDB rounds
        rhs = _npscalar(float(r), type=pa.float64())
    elif l is not None and is_f64(rhs):
        lhs = _npscalar(float(l), type=pa.float64())
    elif isinstance(r, np.float64) and is_int(lhs):     # an integer column against a DOUBLE: compared in double, as DuckDB
        lhs = pc.cast(lhs, pa.float64(), safe=False)
    elif isinstance(l, np.float64) and is_int(rhs):
        rhs = pc.cast(rhs, pa.float64(), safe=False)
    return lhs, rhs


def _align_temporal(lhs, rhs):
    """A timestamp next to a DATE, or to a timestamp with the other kind of zone, as DuckDB compares them: the DATE
    becomes a timestamp of the other side's unit and zone; a naive timestamp (a literal) next to a zoned column is
    an instant in UTC; two zones are one instant either way (the right side takes the left's zone). Units differ
    freely (Arrow compares in the finer one)."""
    tl, tr = getattr(lhs, "type", None), getattr(rhs, "type", None)
    if tl is None or tr is None:
        return lhs, rhs
    ts, date = pa.types.is_timestamp, pa.types.is_date
    if ts(tl) and date(tr):
        return lhs, pc.cast(rhs, tl)
    if date(tl) and ts(tr):
        return pc.cast(lhs, tr), rhs
    if ts(tl) and ts(tr) and tl.tz != tr.tz:
        if tl.tz is None:
            lhs = pc.cast(lhs, pa.timestamp(tl.unit, tr.tz))
        else:
            rhs = pc.cast(rhs, pa.timestamp(tr.unit, tl.tz))
    return lhs, rhs


def _double_vs_int(args, lhs, rhs):
    """An integer array against a DOUBLE literal (an ``np.float64`` constant, F-106) is compared in double, as
    DuckDB does; Arrow would refuse the implicit cast of values past 2**53."""
    def is_int(x):
        return not isinstance(x, pa.Scalar) and hasattr(x, "type") and pa.types.is_integer(x.type)
    def is_double(e):
        return isinstance(e, Expr) and e.op == "lit" and isinstance(e.args[0], np.float64)
    if is_double(args[1]) and is_int(lhs):
        lhs = pc.cast(lhs, pa.float64(), safe=False)
    elif is_double(args[0]) and is_int(rhs):
        rhs = pc.cast(rhs, pa.float64(), safe=False)
    return lhs, rhs


# Ops whose `col <op> literal` form is evaluated natively on dictionary columns.
_DICT_PRED_OPS = frozenset(("eq", "ne", "gt", "ge", "lt", "le", "isin", "startswith", "contains", "like"))

class _LazyCmpOps:
    """MAX comparison ops by name; ``ops`` is only touched when one is looked up."""
    _KEYS = ("gt", "ge", "lt", "le", "eq")

    def __contains__(self, op):
        return op in self._KEYS

    def __getitem__(self, op):
        if op == "gt": return ops.greater
        if op == "ge": return ops.greater_equal
        if op == "lt": return lambda a, b: ops.greater(b, a)
        if op == "le": return lambda a, b: ops.greater_equal(b, a)
        if op == "eq": return ops.equal
        raise KeyError(op)


_CMP_OPS = _LazyCmpOps()


def _is_gpu_max_compatible(acc) -> bool:
    """Return True if MAX's GPU runtime supports this accelerator.

    MAX only supports certain datacenter GPUs (A10, A100, H100, etc.).
    Consumer GPUs (RTX 30xx/40xx) and other unsupported devices raise when
    queried for architecture_name or fail kernel execution with
    CUDA_ERROR_ILLEGAL_ADDRESS.  We probe here to fail fast and cleanly.
    """
    try:
        _ = acc.architecture_name
        return True
    except Exception:
        return False


class GraphCompiler:
    """Compiles a LogicalPlan into a MAX Graph.

    Key design:
    - All Filter nodes are evaluated eagerly in PyArrow *before* the graph is built
      (_strip_filters). This correctly removes rows and makes count() trivially correct.
    - Supports: Scan, Project, Filter (pre-applied), Aggregate, Sort, Limit, Distinct.
    - Sort/Limit/Distinct are stored as post-ops and applied after graph execution.
    - device: "cpu" | "gpu" | "auto"
        "cpu"  -- always use CPU (default)
        "gpu"  -- require a MAX-compatible GPU; raises RuntimeError if unavailable or
                 if the GPU is not supported by the installed MAX version.
        "auto" -- use GPU if MAX-compatible, else fall back to CPU silently
    """

    def __init__(self, device: str = "cpu"):
        # ── device resolution ────────────────────────────────────────────
        self._has_gpu = False
        self._gpu_driver = None
        self._auto_pending = False
        resolved = device.lower()
        self._device_arg = resolved   # kept for subclass auto-switching

        if resolved == "gpu":
            if driver.accelerator_count() == 0:
                raise RuntimeError(
                    "device='gpu' requested but no GPU/accelerator is available"
                )
            acc = driver.Accelerator()
            if not _is_gpu_max_compatible(acc):
                raise RuntimeError(
                    f"device='gpu' requested but the available GPU is not supported "
                    f"by this version of MAX. MAX supports datacenter GPUs (A10, A100, "
                    f"H100, etc.). Consumer GPUs (RTX 30xx/40xx) are not currently "
                    f"supported. Use device='cpu' instead."
                )
            self._gpu_driver = acc
            self._driver_device = self._gpu_driver
            self._device_ref = DeviceRef.GPU(0)
            self._has_gpu = True
            self._session_device = "gpu"
        elif resolved == "auto":
            # Start on the CPU without touching the GPU; the subclass picks the GPU
            # (waiting on the background warm-up) once it knows the query is big enough.
            self._driver_device = None      # created on first use (see the properties below)
            self._device_ref = None
            self._session_device = "cpu"
            self._auto_pending = True
        else:  # "cpu" or any unrecognised string
            self._driver_device = None
            self._device_ref = None
            self._session_device = "cpu"

        self._session_obj = None     # MAX InferenceSession: created on first real graph load

    # The CPU driver device and DeviceRef need the MAX import: made on first use only.
    @property
    def _driver_device(self):
        if self._driver_device_v is None:
            self._driver_device_v = driver.CPU()
        return self._driver_device_v

    @_driver_device.setter
    def _driver_device(self, value):
        self._driver_device_v = value

    @property
    def _device_ref(self):
        if self._device_ref_v is None:
            self._device_ref_v = DeviceRef.CPU()
        return self._device_ref_v

    @_device_ref.setter
    def _device_ref(self, value):
        self._device_ref_v = value

    # A MAX InferenceSession is only needed by the graph (JIT) fallbacks; creating one
    # eagerly costs start-up time on paths that never load a graph.
    @property
    def session(self):
        if self._session_obj is None:
            self._session_obj = self._create_session()
        return self._session_obj

    @session.setter
    def session(self, value):
        self._session_obj = value

    def _create_session(self):
        return engine.InferenceSession(devices=[self._driver_device])

    # ── Post-op extraction ───────────────────────────────────────────
    @classmethod
    def _extract_post_ops(cls, plan):
        """Peel off Sort/Limit/Distinct from the top of the plan tree.

        Returns (core_plan, post_ops) where post_ops is a list of
        nodes in application order (innermost first).
        """
        post_ops = []
        while isinstance(plan, (Sort, Limit, Distinct, Tail)):
            post_ops.append(plan)
            plan = plan.input
        post_ops.reverse()  # innermost first = correct application order
        return plan, post_ops

    @staticmethod
    def _tiebreak_names(plan):
        """Output names of the group keys of the Aggregate under `plan` (Project / Filter nodes over it),
        as `plan` exposes them. A Project that drops a key (or computes a column in its place)
        takes it out: nothing is left to tie-break on for that key."""
        projects = []
        while isinstance(plan, (Project, Filter)):
            if isinstance(plan, Project):               # a Filter keeps every name
                projects.append(plan)
            plan = plan.input
        if not (isinstance(plan, Aggregate) and plan.group_by):
            return []
        names = [e._alias or (e.args[0] if e.op == "col" else None) for e in plan.group_by]
        for prj in reversed(projects):                      # innermost Project first
            out = []
            for n in names:
                hit = [e for e in prj.exprs if e.op == "col" and e.args[0] == n] if n is not None else []
                out.append(hit[0]._alias or n if hit else None)
            names = out
        return [n for n in names if n is not None]

    @classmethod
    def _key_tiebreak(cls, plan, post_ops):
        """ORDER BY right above a group-by (or above Projects over one that keep its keys): add the
        group keys (ascending) as the last sort columns, so ties come out in key order on every
        path, as the native executor and `ORDER BY ..., keys` in DuckDB do (a hash table's own
        order is not deterministic)."""
        if not (post_ops and isinstance(post_ops[0], Sort)):
            return post_ops
        names = cls._tiebreak_names(plan)
        if not names:
            return post_ops
        srt = post_ops[0]
        have = {e.args[0] for e in srt.by if e.op == "col"}
        desc = list(srt.descending) if isinstance(srt.descending, (list, tuple)) \
            else [bool(srt.descending)] * len(srt.by)
        by = list(srt.by)
        for name in names:
            if name not in have:
                by.append(Expr("col", name))
                desc.append(False)
                have.add(name)
        return [Sort(srt.input, by, desc)] + list(post_ops[1:])

    @classmethod
    def _apply_post_ops(cls, table: pa.Table, post_ops: list) -> pa.Table:
        """Apply Sort/Limit/Distinct operations on the Arrow result table.

        This is a fallback for the basic GraphCompiler. The CustomOpsCompiler
        overrides this to use MAX Graph ops + Mojo kernels instead.
        """
        for node in post_ops:
            if isinstance(node, Sort):
                sort_keys = [(e.args[0], "descending" if d else "ascending")
                             for e, d in zip(node.by, node.descending)]
                idx = pc.sort_indices(table, sort_keys=sort_keys)
                table = table.take(idx)
            elif isinstance(node, Limit):
                table = table.slice(node.offset, node.n)
            elif isinstance(node, Distinct):
                cols = node.subset or table.column_names
                table = _distinct_rows(table.select(cols)) if table.num_rows else table.select(cols)
            elif isinstance(node, Tail):
                table = table.slice(max(0, table.num_rows - node.n), node.n)
        return table

    def compile_and_run(self, plan) -> pa.Table:
        """Apply filters eagerly in PyArrow, then compile the rest to a MAX Graph."""
        # Peel off Sort/Limit/Distinct from top of plan
        core_plan, post_ops = self._extract_post_ops(plan)
        post_ops = self._key_tiebreak(core_plan, post_ops)

        core_plan = self._strip_filters(core_plan)
        scan = self._find_scan(core_plan)
        col_names = scan.table.column_names
        col_arrays = {name: np.array(scan.table[name]) for name in col_names}

        input_types = [
            TensorType(_max_dtype(col_arrays[n]), list(col_arrays[n].shape), self._device_ref)
            for n in col_names
        ]

        graph = Graph(name="mxframe_query", input_types=input_types)
        with graph:
            input_nodes = {name: graph.inputs[i] for i, name in enumerate(col_names)}
            result_nodes = self._visit_plan(core_plan, input_nodes)
            graph.output(*result_nodes.values())

        model = self.session.load(graph)
        output_vals = model.execute(*[col_arrays[n] for n in col_names])
        result_names = list(result_nodes.keys())
        arrays = [_npa(_np_of(t)) for t in output_vals]
        result_table = pa.Table.from_arrays(arrays, names=result_names)

        # Apply Sort/Limit/Distinct as post-ops
        if post_ops:
            result_table = self._apply_post_ops(result_table, post_ops)

        return result_table

    @staticmethod
    def _eval_predicate(expr, table: pa.Table):
        """Evaluate a filter predicate against a PyArrow table."""
        op, args = expr.op, expr.args
        if op == "col":
            arr = table.column(args[0])
            if pa.types.is_dictionary(arr.type):
                arr = _decode_dict(arr)
            if isinstance(arr, pa.ChunkedArray):
                # Single-chunk: return Array directly, no 50ms copy from combine_chunks.
                if len(arr.chunks) == 1:
                    return arr.chunks[0]
                return _combine(arr)
            return arr
        if op == "lit":
            # An Arrow scalar, not the Python value: PyArrow converting a Python
            # literal inside a compute call imports pandas (~150-200 ms, once).
            import datetime as _dt
            v = args[0]
            return _npscalar(v) if isinstance(v, (bool, int, float, str, _dt.date, np.datetime64)) else v
        if op in _DICT_PRED_OPS:
            native = _dict_predicate(expr, table)
            if native is not None:
                return native
        if op in _PC_CMP_OPS:
            lhs = GraphCompiler._eval_predicate(args[0], table)
            rhs = GraphCompiler._eval_predicate(args[1], table)
            if op not in ("and", "or"):
                lhs, rhs = _align_literals(lhs, rhs)
                lhs, rhs = _double_vs_int(args, lhs, rhs)
                lhs, rhs = _align_temporal(lhs, rhs)
            return _PC_CMP_OPS[op](lhs, rhs)
        if op == "not":
            return pc.invert(GraphCompiler._eval_predicate(args[0], table))
        if op == "is_null":
            return pc.is_null(GraphCompiler._eval_predicate(args[0], table))
        if op == "isin":
            if isinstance(args[0], Expr) and args[0].op == "str_slice" and isinstance(args[1], (list, tuple)):
                # str_slice(col, ...).isin([...]): one native pass, no sliced array (F-043)
                from . import native_exec
                src = GraphCompiler._eval_predicate(args[0].args[0], table)
                got = native_exec.try_str_slice_in(src, args[0].args[1], args[0].args[2], list(args[1]))
                if got is not None:
                    return got
            col_arr = GraphCompiler._eval_predicate(args[0], table)
            if isinstance(args[1], (list, tuple)):
                # a utf8 column against string values: one native pass (F-043)
                from . import native_exec
                got = native_exec.try_str_slice_in(col_arr, 0, None, list(args[1]))
                if got is not None:
                    return got
            return _is_in(col_arr, args[1])
        if op == "str_slice":
            from .custom_ops import _str_slice
            return _str_slice(GraphCompiler._eval_predicate(args[0], table), args[1], args[2])
        if op == "startswith":
            col_arr = GraphCompiler._eval_predicate(args[0], table)
            return pc.starts_with(col_arr, pattern=args[1])
        if op == "contains":
            col_arr = GraphCompiler._eval_predicate(args[0], table)
            return pc.match_substring(col_arr, pattern=args[1])
        if op == "like":
            from .str_patterns import match_like
            return match_like(GraphCompiler._eval_predicate(args[0], table), args[1], args[2], args[3])
        if op == "case_when":
            return case_when_arrow(GraphCompiler._eval_predicate(args[0], table),
                                   *(case_literal(a.args[0]) if a.op == "lit" else GraphCompiler._eval_predicate(a, table)
                                     for a in args[1:]))
        if op == "coalesce":
            return coalesce_arrow(*branch_values(args, lambda a: GraphCompiler._eval_predicate(a, table)))
        if op == "abs":
            return abs_arrow(GraphCompiler._eval_predicate(args[0], table))
        if op == "add_us":
            return add_interval_arrow(GraphCompiler._eval_predicate(args[0], table), args[1])
        if op == "cast":
            return cast_arrow(GraphCompiler._eval_predicate(args[0], table), args[1])
        if op == "year":
            col_arr = GraphCompiler._eval_predicate(args[0], table)
            if col_arr.type in (pa.int32(), pa.int64()):
                return pc.cast(pc.divide(col_arr, _npscalar(10000, type=pa.int32())), pa.int32())
            return pc.year(col_arr)
        if op in ("and", "or", "__and__", "__or__"):
            lhs = GraphCompiler._eval_predicate(args[0], table)
            rhs = GraphCompiler._eval_predicate(args[1], table)
            return pc.and_kleene(lhs, rhs) if "and" in op else pc.or_kleene(lhs, rhs)
        # Arithmetic ops inside predicates (e.g. lit(0.2) * col("avg_qty") as RHS of comparison)
        if op == "mul":
            lhs = GraphCompiler._eval_predicate(args[0], table)
            rhs = GraphCompiler._eval_predicate(args[1], table)
            return _checked_arith("mul", lhs, rhs)
        if op == "add":
            lhs = GraphCompiler._eval_predicate(args[0], table)
            rhs = GraphCompiler._eval_predicate(args[1], table)
            return _checked_arith("add", lhs, rhs)
        if op == "sub":
            lhs = GraphCompiler._eval_predicate(args[0], table)
            rhs = GraphCompiler._eval_predicate(args[1], table)
            return _checked_arith("sub", lhs, rhs)
        if op == "mod":
            return _modulo(GraphCompiler._eval_predicate(args[0], table), GraphCompiler._eval_predicate(args[1], table),
                           decimal=len(args) > 2)
        if op == "div":
            lhs = GraphCompiler._eval_predicate(args[0], table)
            rhs = GraphCompiler._eval_predicate(args[1], table)
            return pc.divide(lhs, rhs)
        raise NotImplementedError(f"Cannot evaluate predicate op '{op}' in PyArrow.")

    @classmethod
    def _strip_filters(cls, plan):
        """Recursively remove all Filter nodes, applying them eagerly to the Scan."""
        if isinstance(plan, Scan): return plan
        if isinstance(plan, Join):
            return Join(cls._strip_filters(plan.left), cls._strip_filters(plan.right),
                        plan.left_on, plan.right_on, plan.how)
        if isinstance(plan, Filter):
            clean_inner = cls._strip_filters(plan.input)
            scan = cls._find_scan_static(clean_inner)
            mask = cls._eval_predicate(plan.predicate, scan.table)
            filtered_scan = Scan(scan.table.filter(mask))
            return cls._replace_scan(clean_inner, filtered_scan)
        if isinstance(plan, Project):
            return Project(cls._strip_filters(plan.input), plan.exprs)
        if isinstance(plan, Aggregate):
            return Aggregate(cls._strip_filters(plan.input), plan.group_by, plan.aggs)
        if isinstance(plan, Sort):
            return Sort(cls._strip_filters(plan.input), plan.by, plan.descending)
        if isinstance(plan, Limit):
            return Limit(cls._strip_filters(plan.input), plan.n, plan.offset)
        if isinstance(plan, Distinct):
            return Distinct(cls._strip_filters(plan.input), plan.subset)
        if isinstance(plan, Tail):
            return Tail(cls._strip_filters(plan.input), plan.n)
        if hasattr(plan, "input"):
            plan.input = cls._strip_filters(plan.input)
        return plan

    @classmethod
    def _replace_scan(cls, plan, new_scan):
        """Replace the Scan leaf in a plan tree."""
        if isinstance(plan, Scan): return new_scan
        if isinstance(plan, Join):
            raise ValueError("_replace_scan: Join should have been materialized before this point")
        if isinstance(plan, Project): return Project(cls._replace_scan(plan.input, new_scan), plan.exprs)
        if isinstance(plan, Aggregate): return Aggregate(cls._replace_scan(plan.input, new_scan), plan.group_by, plan.aggs)
        if isinstance(plan, Sort): return Sort(cls._replace_scan(plan.input, new_scan), plan.by, plan.descending)
        if isinstance(plan, Limit): return Limit(cls._replace_scan(plan.input, new_scan), plan.n, plan.offset)
        if isinstance(plan, Distinct): return Distinct(cls._replace_scan(plan.input, new_scan), plan.subset)
        if isinstance(plan, Tail): return Tail(cls._replace_scan(plan.input, new_scan), plan.n)
        if hasattr(plan, "input"): plan.input = cls._replace_scan(plan.input, new_scan)
        return plan

    @staticmethod
    def _find_scan_static(plan):
        if isinstance(plan, Scan): return plan
        if isinstance(plan, Join):
            raise ValueError("_find_scan: Join should have been materialized before this point")
        if hasattr(plan, "input"): return GraphCompiler._find_scan_static(plan.input)
        raise ValueError(f"No Scan found in plan: {type(plan)}")

    def _find_scan(self, plan): return self._find_scan_static(plan)

    def _visit_plan(self, plan, nodes):
        if isinstance(plan, Scan): return nodes
        elif isinstance(plan, Join):
            raise NotImplementedError("Join must be materialized before graph compilation")
        elif isinstance(plan, Project): return self._visit_project(plan, nodes)
        elif isinstance(plan, Filter): return self._visit_filter(plan, nodes)
        elif isinstance(plan, Aggregate): return self._visit_aggregate(plan, nodes)
        raise NotImplementedError(f"Unsupported plan node: {type(plan)}")

    def _visit_project(self, plan, nodes):
        upstream = self._visit_plan(plan.input, nodes)
        out = {}
        for i, expr in enumerate(plan.exprs):
            name = expr._alias or f"col_{i}"
            out[name] = self._visit_expr(expr, upstream)
        return out

    def _visit_filter(self, plan, nodes):
        upstream = self._visit_plan(plan.input, nodes)
        mask = self._visit_expr(plan.predicate, upstream)
        filtered = {}
        for name, node in upstream.items():
            filtered[name] = ops.mul(node, ops.cast(mask, node.type.dtype))
        return filtered

    def _visit_aggregate(self, plan, nodes):
        """Global (non-grouped) aggregation via built-in MAX ops."""
        upstream = self._visit_plan(plan.input, nodes)
        out = {}
        for i, expr in enumerate(plan.aggs):
            name = expr._alias or f"agg_{i}"
            out[name] = self._visit_expr(expr, upstream)
        return out

    def _visit_expr(self, expr, nodes):
        """Translate an Expr tree into MAX graph ops."""
        op, args = expr.op, expr.args
        if op == "col": return nodes[args[0]]
        if op == "lit":
            val = args[0]
            if isinstance(val, int): return ops.constant(val, dtype=DType.int64, device=self._device_ref)
            elif isinstance(val, float): return ops.constant(val, dtype=DType.float64, device=self._device_ref)
            return ops.constant(val, dtype=DType.float32, device=self._device_ref)
        if op == "add": return ops.add(self._visit_expr(args[0], nodes), self._visit_expr(args[1], nodes))
        if op == "sub": return ops.sub(self._visit_expr(args[0], nodes), self._visit_expr(args[1], nodes))
        if op == "mul": return ops.mul(self._visit_expr(args[0], nodes), self._visit_expr(args[1], nodes))
        if op == "div": return ops.div(self._visit_expr(args[0], nodes), self._visit_expr(args[1], nodes))
        if op in _CMP_OPS:
            return _CMP_OPS[op](self._visit_expr(args[0], nodes), self._visit_expr(args[1], nodes))
        if op == "sum": return ops.sum(self._visit_expr(args[0], nodes), axis=0)
        if op == "min": return ops.min(self._visit_expr(args[0], nodes), axis=0)
        if op == "max": return ops.max(self._visit_expr(args[0], nodes), axis=0)
        if op == "mean": return ops.mean(self._visit_expr(args[0], nodes), axis=0)
        if op == "count":
            col_node = self._visit_expr(args[0], nodes)
            n = col_node.type.shape[0]
            return ops.constant(np.array([int(n)], dtype=np.int64), dtype=DType.int64, device=self._device_ref)
        if op == "ne":
            lhs = self._visit_expr(args[0], nodes)
            rhs = self._visit_expr(args[1], nodes)
            # ne = 1 - eq (bool→int32)
            eq_node = ops.cast(ops.equal(lhs, rhs), DType.int32)
            one = ops.constant(np.array([1], dtype=np.int32), dtype=DType.int32, device=self._device_ref)
            return ops.sub(one, eq_node)
        if op == "not":
            inner = ops.cast(self._visit_expr(args[0], nodes), DType.int32)
            one = ops.constant(np.array([1], dtype=np.int32), dtype=DType.int32, device=self._device_ref)
            return ops.sub(one, inner)
        if op == "case_when":
            cond  = ops.cast(self._visit_expr(args[0], nodes), DType.float32)
            then  = ops.cast(self._visit_expr(args[1], nodes), DType.float32)
            else_ = ops.cast(self._visit_expr(args[2], nodes), DType.float32)
            one  = ops.constant(np.array([1.0], dtype=np.float32), dtype=DType.float32, device=self._device_ref)
            # cond * then + (1 - cond) * else_
            return ops.add(
                ops.mul(cond, then),
                ops.mul(ops.sub(one, cond), else_),
            )
        if op in ("isin", "startswith"):
            raise NotImplementedError(
                f"op '{op}' involves strings — pre-compute as a derived column "
                "before passing to the MAX graph."
            )
        raise NotImplementedError(f"Unsupported expression op: '{op}'")

